import assert from 'node:assert/strict';
import {createRequire} from 'node:module';
import {writeFile,readFile} from 'node:fs/promises';
import path from 'node:path';
const require=createRequire(process.env.PLAYWRIGHT_PACKAGE||'/home/saga-server/site-uri/cesiro1-site/e2e/package.json');const {chromium}=require('playwright');
const root=path.resolve(import.meta.dirname,'..'),base='http://127.0.0.1:4160';const catalog=JSON.parse(await readFile(path.join(root,'docs/usecase-catalog-ro.json'),'utf8'));
const report={started:new Date().toISOString(),checks:[],errors:[],csp:[]};const browser=await chromium.launch({headless:true});
const ready=page=>page.waitForSelector('#app:not([data-ssr]) main h1');
try{
 const context=await browser.newContext({viewport:{width:1440,height:1000},reducedMotion:'reduce'});await context.addInitScript(()=>{window.policyViolations=[];document.addEventListener('securitypolicyviolation',e=>window.policyViolations.push({directive:e.violatedDirective,blocked:e.blockedURI}));});const page=await context.newPage();page.on('pageerror',e=>report.errors.push(e.message));
 const existingApp=await page.request.get(base+'/api/app/i18n?lang=ro');assert.equal(existingApp.status(),200);const appBundle=await existingApp.json();assert.equal(appBundle.locale,'ro');assert.ok(Object.keys(appBundle.messages).length>=153);report.checks.push({type:'existing-app-translation-api-preserved',status:'passed'});
 for(const lang of ['en','de','fr','es','ro','hu','bg']){
  await page.goto(base+'/uses?lang='+lang);await ready(page);assert.equal(await page.locator('.usecase-card').count(),36);const state=await page.evaluate(()=>({title:document.title,description:document.querySelector('meta[name=description]').content,canonical:document.getElementById('seo-canonical').href,json:JSON.parse(document.getElementById('seo-jsonld').textContent),alternates:document.querySelectorAll('link[hreflang]').length,overflow:document.documentElement.scrollWidth>innerWidth+1}));assert.ok(state.title.includes('EVA'));assert.ok(state.description.length>30);assert.equal(state.canonical,'https://3dscan.eva-org.com/uses?lang='+lang);assert.equal(state.json.inLanguage,lang);assert.equal(state.alternates,8);assert.equal(state.overflow,false);assert.deepEqual(await page.evaluate(()=>window.policyViolations),[]);
  for(const category of [...new Set(catalog.items.map(i=>i.category))]){await page.click(`[data-use-filter="${category}"]`);assert.equal(await page.locator('.usecase-card').count(),6);}
  report.checks.push({type:'36-usecases-six-filters-and-seo',lang,status:'passed'});
 }
 await page.goto(base+'/uses?lang=ro');await ready(page);await page.fill('#use-search','zzzz-no-result');assert.equal(await page.locator('.usecase-card').count(),0);assert.equal(await page.locator('.uses-empty').count(),1);await page.fill('#use-search','imprimare');assert.ok(await page.locator('.usecase-card').count()>0);await page.locator('#use-search').evaluate(e=>{e.focus();e.setSelectionRange(2,4);});await page.evaluate(()=>dispatchEvent(new Event('online')));await page.waitForTimeout(350);assert.deepEqual(await page.locator('#use-search').evaluate(e=>({focused:document.activeElement===e,start:e.selectionStart,end:e.selectionEnd,value:e.value})),{focused:true,start:2,end:4,value:'imprimare'});report.checks.push({type:'search-empty-results-and-focus-selection-after-refresh',status:'passed'});
 const time=await page.evaluate(()=>performance.timeOrigin);await page.selectOption('#language','de');await page.waitForFunction(()=>document.documentElement.lang==='de');assert.equal(await page.evaluate(()=>performance.timeOrigin),time);assert.equal(await page.getAttribute('#seo-canonical','href'),'https://3dscan.eva-org.com/uses?lang=de');await page.locator('footer [data-route="/people"]').click();await ready(page);assert.equal(await page.getAttribute('#seo-canonical','href'),'https://3dscan.eva-org.com/people?lang=de');assert.equal(await page.locator('.people-layout img').getAttribute('src'),'/assets/campaign/02-face.webp');assert.equal(await page.evaluate(()=>JSON.parse(document.getElementById('seo-jsonld').textContent).inLanguage),'de');assert.deepEqual(await page.evaluate(()=>window.policyViolations),[]);report.checks.push({type:'spa-locale-route-metadata-jsonld-csp',status:'passed'});
 const anchor=catalog.items.at(-1).id;await page.goto(base+'/uses?lang=ro#usecase-'+anchor);await ready(page);await page.waitForTimeout(200);const box=await page.locator('#usecase-'+anchor).boundingBox();assert.ok(box.y>=0&&box.y<300);assert.ok(box.y+box.height>0);report.checks.push({type:'deep-link-anchor-after-hydration',status:'passed'});
 await page.goto(base+'/uses?lang=ro#bad%');await ready(page);assert.equal(await page.locator('.usecase-card').count(),36);report.checks.push({type:'malformed-fragment-keeps-page-working',status:'passed'});
 for(const [route,files] of [['/objects',['06-architect']],['/measure',['07-mario-walls']],['/spaces',['08-design-couple','09-repair-foreman']],['/people',['02-face']]]){await page.goto(base+route+'?lang=ro');await ready(page);for(const file of files){const img=page.locator(`img[src="/assets/campaign/${file}.webp"]`);assert.equal(await img.count(),1);await img.evaluate(async i=>{await i.decode();});}report.checks.push({type:'scenario-images',route,status:'passed'});}
 await page.goto(base+'/spaces?lang=ro');await ready(page);await page.screenshot({path:path.join(root,'docs/validation/spaces-usecases.png'),fullPage:true});await page.goto(base+'/uses?lang=ro');await ready(page);await page.click('[data-use-filter="repair_construction"]');await page.screenshot({path:path.join(root,'docs/validation/uses-desktop.png'),fullPage:true});await page.goto(base+'/?lang=ro');await ready(page);await page.screenshot({path:path.join(root,'docs/validation/scenarios-home.png'),fullPage:true});
 await page.setViewportSize({width:390,height:844});await page.goto(base+'/uses?lang=ro');await ready(page);await page.click('[data-use-filter="interior_design"]');assert.equal(await page.evaluate(()=>document.documentElement.scrollWidth>innerWidth+1),false);await page.screenshot({path:path.join(root,'docs/validation/uses-mobile.png'),fullPage:true});report.checks.push({type:'mobile-usecase-layout',status:'passed'});report.csp.push(...await page.evaluate(()=>window.policyViolations));await context.close();
 const nojs=await browser.newContext({javaScriptEnabled:false,viewport:{width:390,height:844}});const p=await nojs.newPage();await p.goto(base+'/uses?lang=ro');assert.equal(await p.locator('article[id^="usecase-"]').count(),36);assert.equal(await p.getAttribute('html','lang'),'ro');assert.ok(await p.locator('a[href="/people?lang=ro"]').first().isVisible());assert.equal(await p.evaluate(()=>document.documentElement.scrollWidth>innerWidth+1),false);report.checks.push({type:'indexable-usable-html-without-javascript',status:'passed'});await nojs.close();assert.deepEqual(report.errors,[]);assert.deepEqual(report.csp,[]);report.status='passed';
}catch(error){report.status='failed';report.errors.push(error.stack);process.exitCode=1;}finally{await browser.close();report.finished=new Date().toISOString();await writeFile(path.join(root,'docs/validation/discovery-report.json'),JSON.stringify(report,null,2));console.log(JSON.stringify({status:report.status,checks:report.checks.length,errors:report.errors,csp:report.csp}));}
